import java.util.*;

public class Main {
    static int[][] reconstructQueue(int[][] people) {
        List<int[]> remaining = new ArrayList<>(Arrays.asList(people));
        List<int[]> result = new ArrayList<>();

        while (!remaining.isEmpty()) {
            int maxH = -1;
            for (int[] p : remaining) maxH = Math.max(maxH, p[0]);
            int[] chosen = null;
            for (int[] p : remaining) {
                if (p[0] == maxH && (chosen == null || p[1] < chosen[1])) chosen = p;
            }
            result.add(chosen[1], chosen);
            remaining.remove(chosen);
        }
        return result.toArray(new int[0][]);
    }

    public static void main(String[] args) {
        int[][] result = reconstructQueue(new int[][]{{7, 0}, {4, 4}, {7, 1}, {5, 0}, {6, 1}, {5, 2}});
        for (int[] p : result) System.out.print(Arrays.toString(p) + " ");
        System.out.println();
    }
}

