#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> reconstructQueue(vector<vector<int>>& people) {
    vector<vector<int>> remaining = people;
    vector<vector<int>> result;

    while (!remaining.empty()) {
        int maxH = -1;
        for (auto& p : remaining) maxH = max(maxH, p[0]);
        int chosenIdx = -1;
        for (int i = 0; i < (int)remaining.size(); i++) {
            if (remaining[i][0] == maxH && (chosenIdx == -1 || remaining[i][1] < remaining[chosenIdx][1])) {
                chosenIdx = i;
            }
        }
        vector<int> chosen = remaining[chosenIdx];
        result.insert(result.begin() + chosen[1], chosen);
        remaining.erase(remaining.begin() + chosenIdx);
    }
    return result;
}

int main() {
    vector<vector<int>> people = {{7, 0}, {4, 4}, {7, 1}, {5, 0}, {6, 1}, {5, 2}};
    for (auto& p : reconstructQueue(people)) cout << "[" << p[0] << "," << p[1] << "] ";
    cout << endl;
    return 0;
}

